let media={},baseline=[],experience='form';
function silk(h,size=''){
 const i=race.horses.findIndex(x=>x.name===h.name);return i<0?'':`<span class="race-silk ${size}" role="img" aria-label="${esc(h.display)} silks" style="--sprite:url('assets/silks-r${race.number}.png?meeting=${data.date}');--silk-x:${i};--silk-count:${race.horses.length}"></span>`;
}
function horsePhoto(h,variant='card'){
 const p=media[h.name];if(!p)return '<p class="photo-note">Verified photo unavailable</p>';return `<figure class="horse-photo ${variant} ${p?'':'no-photo'}">${p?`<img src="${esc(p.src)}" alt="${esc(h.display)}" loading="lazy" onerror="this.hidden=true;this.parentElement.classList.add('photo-failed')"><figcaption><a href="${esc(p.source)}" target="_blank" rel="noopener">${esc(p.credit)} ↗</a></figcaption>`:`<div class="photo-placeholder">${silk(h,'hero')}<span>Horse photo unavailable</span></div>`}<span class="image-error">Photo unavailable</span></figure>`;
}
function currentRunner(h){return lateMail?.meeting?.races.find(r=>r.number===race.number)?.runners.find(r=>r.number===h.number)}
function shortSentiment(h){const {first,other}=runnerSentiment(h),current=currentRunner(h);if(current?.scratched&&!h.scratched)return '<p class="short-sentiment late-scratch">Late scratching · see Late mail</p>';return `<p class="short-sentiment">${first.length?`${first.length} ${first.length===1?'guide pick':'guide picks'}${other.length?` · ${other.length} mentions`:''}`:other.length?`${other.length} guide mentions`:'No guide picks in this sample'}</p>`}
function selectionConfidence(h,options={}){return M.confidence(h,options)}
function confidenceMarkup(h,options){const evaluated=selectionConfidence(h,options),c=options?.assessment&&!(options.live&&evaluated.reason==='Current race information needs a fresh check.')?options.assessment:evaluated;return `<details class="selection-confidence ${c.level}"><summary>Confidence: ${esc(c.label.replace(/ confidence/i,''))}</summary><p>${esc(c.reason)} Evidence strength, not win probability.</p></details>`}
function runnerEvidenceMarkup(h){if(!h)return '';const crowd=M.crowd(editorial?.sources||[],race,{asOf:data.date}),count=crowd.support[h.name]?.guides.length||0,rank=baseline.filter(x=>x.eligible&&x.history.length).findIndex(x=>x.name===h.name)+1;return `<div class="runner-evidence">${crowd.guideCount?`<span><b>${count}/${crowd.guideCount}</b> first picks</span>`:'<span>No published first-pick coverage</span>'}${rank?`<span><b>#${rank}</b> form ladder</span>`:''}</div>`}

function renderSimple(){
 const top=baseline.filter(h=>h.eligible&&!currentRunner(h)?.scratched&&h.history.length).slice(0,3),leader=top[0];document.getElementById('shortlistStatus').textContent='ORIGINAL FORM';
 document.getElementById('simpleVerdict').innerHTML=leader?'<p>Original form ladder · published tip support</p>':'<p>No eligible runners with race history in this snapshot.</p>';
 const unknown=race.horses.filter(h=>!h.scratched&&!h.emergency&&!h.history.length).length;if(unknown)document.getElementById('simpleVerdict').innerHTML+=`<details class="field-coverage"><summary>${unknown} runners have no race history in this sample</summary><p>Check their trials and jump-outs in the full field. The race-history ladder cannot assess them fully.</p></details>`;
 document.getElementById('contenderCards').innerHTML=top.map((h,i)=>{const w=M.wins(graph,h.name,race.distance)[0],last=h.history[0],reason=w?`${fmt(w.delta)}L ahead of ${display(w.other)} at ${w.edge.race.track}.`:last?`${last.pos===1?'Won':`${last.pos}/${last.total} in`} the latest start at ${last.track}.`:'Race and trial context available below.';return `<article class="contender-card">${media[h.name]?`<div class="contender-image">${horsePhoto(h)}<span class="contender-rank">${i+1}<span> ORIGINAL FORM</span></span></div>`:''}<div class="contender-body"><div class="contender-name"><span class="rank-flag">${i+1}</span>${silk(h,'large')}<div><span class="eyebrow">NO. ${h.number}</span><h4>${esc(h.display)}</h4></div></div>${runnerEvidenceMarkup(h)}<p class="contender-reason">${esc(reason)}</p>${confidenceMarkup(h,{separateGroups:new Set(baseline.filter(x=>x.eligible&&x.history.length).map(x=>x.component)).size>1})}${runnerInputSummary(h)}<button class="contender-explore" data-inspect="${esc(h.name)}" aria-label="View ${esc(h.display)}">View runner <span>↗</span></button></div></article>`}).join('');document.querySelectorAll('[data-inspect]').forEach(b=>b.onclick=()=>inspectRunner(b.dataset.inspect));
}

function runnerInputSummary(h){const c=h.inputs;if(!c)return '';const days=h.daysSinceRun??(h.history.length?Math.round((Date.parse(data.date)-Date.parse(h.history[0].date))/86400000):null);const flags=[];if(!h.history.length)flags.push('No race history');else if(days>60)flags.push(`Returning after ${days} days`);if(c.trials?.length)flags.push(`${c.trials.length} trial / jump-out records`);return flags.length?`<p class="input-flags">${flags.map(esc).join(' · ')}</p>`:''}
function runnerInputs(h){const c=h.inputs;if(!c)return '';const stats=c.stats||{},trials=c.trials||[];return `<details class="runner-inputs"><summary>Fitness, ground &amp; trial context</summary><p class="mail-quiet">Career records are context, not a rating bonus. Trials do not enter the race-history ladder.</p><div class="input-stats">${['career','track','distance','firstUp','Soft','Heavy'].filter(k=>stats[k]).map(k=>`<div><span>${esc({career:'Career',track:'Flemington',distance:'Distance',firstUp:'First-up',Soft:'Soft',Heavy:'Heavy'}[k])}</span><b>${esc(stats[k])}</b></div>`).join('')}</div><small>Starts : wins, seconds, thirds</small>${trials.length?`<h4>Latest trials / jump-outs</h4>${trials.slice(0,2).map(t=>`<p>${shortDate(t.date)} · ${esc(t.track)} ${t.distance}m · ${t.pos}/${t.total}</p>`).join('')}`:'<p>No trial record in this source sample.</p>'}${c.stewards?.length?`<h4>Stewards’ context</h4>${c.stewards.map(t=>`<p>${shortDate(t.date)} · ${esc(t.summary)}</p>`).join('')}`:''}<a href="${esc(race.source)}" target="_blank" rel="noopener">Runner form source ↗</a></details>`}
